```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Request logging
app.use(morgan('combined'));

// JSON and URL encoded body parser with limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Users endpoint with validation
app.get('/users',
  [
    // Example validation for query parameters
    query('id').optional().isInt().withMessage('ID must be an integer'),
    query('name').optional().isString().withMessage('Name must be a string')
  ],
  (req, res) => {
  try {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, you would filter users based on validated params
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ status: 'error', message: 'Something broke!' });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ status: 'error', message: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

## Additional Security Recommendations

1. **Environment Variables**: Move sensitive data like ports to environment variables.

2. **CORS**: Add CORS configuration if your app needs to serve cross-origin requests.

3. **HTTPS**: Ensure HTTPS is used in production.

4. **Dependency Security**: Regularly audit dependencies using tools like `npm audit`.

5. **Session Security**: If adding authentication, use secure session management with HttpOnly, Secure cookies.

6. **Input Sanitization**: Sanitize inputs in addition to validation.

7. **Security Testing**: Regularly perform security testing and vulnerability scans.

To implement these improvements, you will need to install these dependencies:

```bash
npm install helmet express-rate-limit express-validator morgan
```

