// Script to verify the validity of credentials in .env.test
const dotenv = require('dotenv');
const { Pool } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');
const stripe = require('stripe');

dotenv.config({ path: '.env.test' });

async function testDatabaseConnection() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('DATABASE_URL not set. Skipping database test.');
    return;
  }

  const pool = new Pool({
    connectionString: databaseUrl,
    ssl: { rejectUnauthorized: false }, // Bypass SSL for testing
  });

  try {
    const client = await pool.connect();
    console.log('✅ Database connection successful.');
    client.release();
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
  } finally {
    await pool.end();
  }
}

async function testAWSKeys() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('AWS keys not set. Skipping AWS test.');
    return;
  }

  const awsConfig = new AWS.Config({
    accessKeyId,
    secretAccessKey,
  });

  try {
    AWS.config.update(awsConfig);
    const sts = new AWS.STS();
    await sts.getCallerIdentity().promise();
    console.log('✅ AWS keys are valid.');
  } catch (error) {
    console.log('❌ AWS keys are invalid:', error.message);
  }
}

async function testAnthropicAPI() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('ANTHROPIC_API_KEY not set. Skipping Anthropic test.');
    return;
  }

  try {
    const response = await axios.get('https://api.anthropic.com/v1/models', {
      headers: { 'Authorization': `Bearer ${apiKey}` },
    });
    console.log('✅ Anthropic API key is valid.');
  } catch (error) {
    console.log('❌ Anthropic API key is invalid:', error.message);
  }
}

async function testStripeAPI() {
  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log('STRIPE_SECRET_KEY not set. Skipping Stripe test.');
    return;
  }

  try {
    const stripeClient = stripe(apiKey);
    await stripeClient.customers.list({ limit: 1 });
    console.log('✅ Stripe API key is valid.');
  } catch (error) {
    console.log('❌ Stripe API key is invalid:', error.message);
  }
}

async function testLogfireToken() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('LOGFIRE_TOKEN not set. Skipping Logfire test.');
    return;
  }

  try {
    const response = await axios.post('https://api.logfire.ai/graphql', {
      query: '{ __typename }',
    }, {
      headers: { 'Authorization': `Bearer ${token}` },
    });
    console.log('✅ Logfire token is valid.');
  } catch (error) {
    console.log('❌ Logfire token is invalid:', error.message);
  }
}

async function runTests() {
  console.log('Testing database connection...');
  await testDatabaseConnection();

  console.log('\nTesting AWS keys...');
  await testAWSKeys();

  console.log('\nTesting Anthropic API...');
  await testAnthropicAPI();

  console.log('\nTesting Stripe API...');
  await testStripeAPI();

  console.log('\nTesting Logfire token...');
  await testLogfireToken();
}

runTests();

