  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with query validation
app.get('/users', validate, (req, res) => {
  const userId = req.query.id;

  if (userId && isNaN(userId)) {
    return res.status(400).json({ error: 'Invalid user ID format' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error Handling Middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// HTTP Server
const httpServer = app.listen(process.env.HTTP_PORT || 3000, () => {
  console.log(`HTTP Server running on port ${process.env.HTTP_PORT || 3000}`);
});

// HTTPS Server (if certificates are available)
if (process.env.HTTPS_ENABLED === 'true') {
  const options = {
    key: fs.readFileSync(process.env.HTTPS_KEY_PATH),
    cert: fs.readFileSync(process.env.HTTPS_CERT_PATH),
  };

  const httpsServer = https.createServer(options, app);
  httpsServer.listen(process.env.HTTPS_PORT || 443, () => {
    console.log(`HTTPS Server running on port ${process.env.HTTPS_PORT || 443}`);
  });
}

module.exports = app;
```

