const axios = require('axios');
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Stripe = require('stripe');

// Load environment variables from .env.test
require('dotenv').config({ path: './.env.test' });

async function checkCredentials() {
  console.log('Starting credential validation...\n');

  // 1. Check Database URL
  console.log('1. Testing PostgreSQL connection...');
  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: 5000, // 5 second timeout
    });
    await client.connect();
    await client.end();
    console.log('✓ Database connection successful\n');
  } catch (error) {
    console.error('✗ Database connection failed:', error.message, '\n');
  }

  // 2. Check AWS Credentials
  console.log('2. Testing AWS credentials...');
  try {
    const sts = new AWS.STS({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1',
    });
    const response = await sts.getCallerIdentity().promise();
    console.log('✓ AWS credentials valid. Account:', response.Account, '\n');
  } catch (error) {
    console.error('✗ AWS credentials invalid:', error.message, '\n');
  }

  // 3. Check Anthropic API Key
  console.log('3. Testing Anthropic API key...');
  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/complete',
      {
        model: 'claude-2',
        prompt: '\n\nHuman: Test connection\n\nAssistant:',
        max_tokens_to_sample: 1,
      },
      {
        headers: {
          'Content-Type': 'application/json',
          'X-API-Key': process.env.ANTHROPIC_API_KEY,
        },
        timeout: 5000,
      }
    );
    if (response.data && response.data.completion) {
      console.log('✓ Anthropic API key valid\n');
    } else {
      console.error('✗ Anthropic API key response unexpected:', response.status, '\n');
    }
  } catch (error) {
    console.error('✗ Anthropic API key invalid:', error.message, '\n');
  }

  // 4. Check Stripe API Key
  console.log('4. Testing Stripe API key...');
  try {
    const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
      apiVersion: '2023-08-16',
    });
    const response = await stripe.balance.retrieve();
    console.log('✓ Stripe API key valid\n');
  } catch (error) {
    console.error('✗ Stripe API key invalid:', error.message, '\n');
  }

  // 5. Check Logfire Token (if applicable)
  console.log('5. Testing Logfire token...');
  try {
    // Logfire may not have a simple ping endpoint, so we'll check for non-empty token
    if (process.env.LOGFIRE_TOKEN && process.env.LOGFIRE_TOKEN.length > 0) {
      console.log('✓ Logfire token is set (validation requires specific endpoint)\n');
    } else {
      console.error('✗ Logfire token is empty\n');
    }
  } catch (error) {
    console.error('✗ Logfire token check failed:', error.message, '\n');
  }

  console.log('Credential validation complete.');
}

checkCredentials().catch(console.error);

